  FT["PH-H8592"] = {"id":"PH-H8592","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_10135_2010.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Dumalinao市","en":"An Act Establishing a National High School in Baranagy Tina, Municipality of Dumalinao, Province of Zamboanga Del Sur to be Known as Tina National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Baranagy Tina, Municipality of Dumalinao, Province of Zamboanga Del Sur to be Known as Tina National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 10135","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-06-03","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_10135_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8592-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Establishment of a National High School. - There is hereby established, under the supervision of the Department of Education, a national high school in Barangay Tina, Municipality of Dumalinao, Province of Zamboanga del Sur to be known as Tina National High School."}},{"id":"PH-H8592-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department's program the operationalization of the Tina National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8592-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementation. - The Secretary of Education shall issue rules and regulations that may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8592-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p122"};
  FT["PH-H8593"] = {"id":"PH-H8593","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_10136_2010.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Converting the Piñan - Mutia Provincial Road Linking the Municipalities of Piñan and Mutia, Province of Zamboanga Del Norte Into a National Road","orig":"An Act Converting the Piñan - Mutia Provincial Road Linking the Municipalities of Piñan and Mutia, Province of Zamboanga Del Norte Into a National Road"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10136","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-06-03","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_10136_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8593-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Piñan - Mutia Provincial Road linking the municipalities of Piñan and Mutia, Province of Zamboanga del Norte is hereby converted into a national road."}},{"id":"PH-H8593-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Public Works and Highways shall issue the necessary rules, orders and circulars to implement the provision of this Act."}},{"id":"PH-H8593-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in a newspaper of general circulation."}}],"pack":"ph-p122"};
